import java.io.IOException;
public class Main {
    static int requireLength(String text) throws IOException {
        if (text.isEmpty()) {
            throw new IOException("empty");
        }
        return text.length();
    }
    public static void main(String[] args) {
        try {
            System.out.println(requireLength("abc"));
        } catch (IOException e) {
            System.out.println("invalid");
        }
    }
}

