        try {
            if (x < 0) throw new IllegalArgumentException("neg");
            if (x == 0) throw new IllegalStateException("zero");
            return "ok";
        } catch (RuntimeException e) {
            return "runtime";
        }
    }
    public static void main(String[] args) {
        System.out.println(kind(-1));
    }
}

